import sys


def add(a, b):
    return a + b


if __name__ == "__main__":
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <num1> <num2>", file=sys.stderr)
        sys.exit(1)
    try:
        n1 = float(sys.argv[1])
        n2 = float(sys.argv[2])
    except ValueError:
        print("Error: Both arguments must be valid numbers", file=sys.stderr)
        sys.exit(1)
    res = add(n1, n2)
    print(int(res) if res.is_integer() else res)
